<script lang="ts">import{onMount}from'svelte';import{csrfHeaders,idempotencyKey}from'$lib/api/client';import{productLabel}from'$lib/product-language';let requests:any[]=[];let request_type='ACCESS',details='',message='',busy=false,loading=true;async function load(){const r=await fetch('/api/v1/me/privacy-requests',{credentials:'include'});if(r.ok)requests=(await r.json()).requests??[];loading=false}async function submit(){busy=true;const r=await fetch('/api/v1/me/privacy-requests',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey(),...csrfHeaders()},body:JSON.stringify({request_type,details})});const d=await r.json().catch(()=>({}));busy=false;message=r.ok?'Request received. We will update this page as it progresses.':d.detail??'Request could not be submitted.';if(r.ok){details='';await load()}}onMount(load)</script>
<svelte:head><title>Your information — Kredit</title></svelte:head><main class="shell workspace privacy"><p class="eyebrow">Settings / Your information</p><h1>You control your information.</h1><p class="lede">Ask to see, correct, download or remove your information. We may need to keep payment records when the law requires it.</p>{#if message}<p class="notice" role="status">{message}</p>{/if}<section><h2>Tell us what you need</h2><label>What should we do?<select disabled={loading} bind:value={request_type}><option value="ACCESS">Show me my information</option><option value="CORRECTION">Correct something</option><option value="DELETION">Remove what can be removed</option><option value="RESTRICTION">Stop using some information</option><option value="OBJECTION">Tell Kredit to stop a use</option><option value="CONSENT_WITHDRAWAL">Take back my permission</option><option value="PORTABILITY">Give me a copy to download</option></select></label><label>Tell us more<textarea disabled={loading} bind:value={details} maxlength="2000" rows="4" placeholder="What information is this about?"></textarea></label><button onclick={submit} disabled={loading||busy||!details}>{busy?'Sending…':'Send my request'}</button></section><section><h2>Requests you sent</h2>{#if requests.length===0}<p>You have not sent a request.</p>{:else}{#each requests as r}<article><strong>{productLabel(r.request_type)}</strong><span>{productLabel(r.state)}</span><p>We aim to finish by {new Date(r.due_at).toLocaleDateString('en-NG')}</p>{#if r.retention_outcome}<p>{r.retention_outcome}</p>{/if}{#if r.export_reference}<p>Your protected copy is ready until {new Date(r.export_expires_at).toLocaleDateString('en-NG')}.</p><a href={`/api/v1/me/privacy-requests/${r.id}/export`}>Download my information</a>{/if}</article>{/each}{/if}</section></main>
<style>.privacy{max-width:52rem}.privacy h1{font-size:clamp(2.4rem,6vw,4.5rem);line-height:1}.privacy section{display:grid;gap:.8rem;margin:1rem 0;padding:1.3rem;border:1px solid var(--color-border);border-radius:1rem;background:var(--color-surface)}label{display:grid;gap:.35rem;font-weight:700}select,textarea,button{padding:.75rem;border:1px solid var(--color-border);border-radius:.65rem;font:inherit}button{background:var(--color-primary);color:white;font-weight:800}.notice{padding:1rem;background:#eef5ff;border-radius:.7rem}article{display:grid;grid-template-columns:1fr auto;gap:.35rem;padding:1rem;border-top:1px solid var(--color-border)}article p{grid-column:1/-1;margin:0}</style>
